"""Date-window membership for the date_window fixture."""

from __future__ import annotations

import datetime


def _parse_date(date_str: str) -> datetime.date:
    """Parse and validate a date string in strict YYYY-MM-DD format."""
    if not isinstance(date_str, str):
        raise ValueError(f"Expected a string, got {type(date_str)}")
    # Check strict format: must be exactly YYYY-MM-DD with zero-padding
    if len(date_str) != 10:
        raise ValueError(f"Invalid date format: {date_str!r}")
    parts = date_str.split("-")
    if len(parts) != 3:
        raise ValueError(f"Invalid date format: {date_str!r}")
    year_str, month_str, day_str = parts
    if len(year_str) != 4 or len(month_str) != 2 or len(day_str) != 2:
        raise ValueError(f"Invalid date format: {date_str!r}")
    # Ensure all parts are digits
    if not (year_str.isdigit() and month_str.isdigit() and day_str.isdigit()):
        raise ValueError(f"Invalid date format: {date_str!r}")
    try:
        return datetime.date(int(year_str), int(month_str), int(day_str))
    except ValueError as e:
        raise ValueError(f"Invalid date: {date_str!r}") from e


def in_any_window(target_date: str, windows: list[tuple[str, str]]) -> bool:
    """Return whether target_date falls inside any date window."""
    # Parse and validate the target date first
    target = _parse_date(target_date)

    # Parse and validate all windows before checking membership
    parsed_windows = []
    for start, end in windows:
        start_date = _parse_date(start)
        end_date = _parse_date(end)
        if start_date > end_date:
            raise ValueError(
                f"Window start {start!r} is after end {end!r}"
            )
        parsed_windows.append((start_date, end_date))

    # Check if target falls in any window
    for start_date, end_date in parsed_windows:
        if start_date <= target <= end_date:
            return True

    return False
